# Synthetic M4A test fixtures for the on-device transcription tests.
# Speech is generated by Windows TTS (David / Hortense) — no microphone access,
# no personal audio. The WAVs are converted to 44.1 kHz stereo AAC (the format
# MediaRecorder produces), so the decoder path is exercised for real.
#
# Usage: powershell -ExecutionPolicy Bypass -File tools\generate_asr_test_audio.ps1
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Speech

$directory = Join-Path $PSScriptRoot '..\app\build\generated\asr-test-assets'
New-Item -ItemType Directory -Force -Path $directory | Out-Null

# --- locate ffmpeg / ffprobe: PATH, then the WinGet Links folder, then the packages folder ---
function Resolve-MediaTool([string]$name) {
    $command = Get-Command $name -ErrorAction SilentlyContinue
    if ($command) { return $command.Source }

    $links = Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Links\$name.exe"
    if (Test-Path $links) { return $links }

    $packages = Join-Path $env:LOCALAPPDATA 'Microsoft\WinGet\Packages'
    if (Test-Path $packages) {
        $found = Get-ChildItem $packages -Filter '*.exe' -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -eq "$name.exe" } |
            Select-Object -First 1
        if ($found) { return $found.FullName }
    }
    throw "$name not found. Install it with: winget install Gyan.FFmpeg"
}

$ffmpeg = Resolve-MediaTool 'ffmpeg'
$ffprobe = Resolve-MediaTool 'ffprobe'
Write-Output "ffmpeg:  $ffmpeg"
Write-Output "ffprobe: $ffprobe"

# --- text used for the fixtures ---
$englishText = 'This is a local speech recognition test. The model should detect English automatically.'
$frenchText = 'Bonjour, ceci est un test de reconnaissance vocale. Le fichier reste sur le t' +
    [char]0xe9 + 'l' + [char]0xe9 + 'phone.'
# The repeated part must not contain any word of the final sentence, so the
# test can prove the tail of a long recording survived.
$finalText = 'Cette phrase de fin est unique et doit survivre.'

# --- Windows TTS: 16 kHz mono WAV (the intermediate format) ---
$format = New-Object System.Speech.AudioFormat.SpeechAudioFormatInfo(
    16000,
    [System.Speech.AudioFormat.AudioBitsPerSample]::Sixteen,
    [System.Speech.AudioFormat.AudioChannel]::Mono
)
$synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
try {
    $synth.SelectVoice('Microsoft David Desktop')
    $synth.SetOutputToWaveFile((Join-Path $directory 'english.wav'), $format)
    $synth.Speak($englishText)

    $synth.SetOutputToNull()
    $synth.SelectVoice('Microsoft Hortense Desktop')
    $synth.SetOutputToWaveFile((Join-Path $directory 'french.wav'), $format)
    $synth.Speak($frenchText)

    $synth.SetOutputToNull()
    $synth.SetOutputToWaveFile((Join-Path $directory 'long_french.wav'), $format)
    # Six repetitions put the final sentence well past the engine's 30 s
    # internal window, so the tail has to survive several windows.
    1..6 | ForEach-Object { $synth.Speak($frenchText) }
    $synth.Speak($finalText)
} finally {
    $synth.Dispose()
}

# --- WAV -> 44.1 kHz stereo AAC (M4A), the format MediaRecorder writes ---
function Convert-ToM4a([string]$wav, [string]$m4a) {
    & $ffmpeg -hide_banner -loglevel error -y -i $wav -ar 44100 -ac 2 -c:a aac -b:a 128k $m4a
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for $wav" }
}

Convert-ToM4a (Join-Path $directory 'english.wav') (Join-Path $directory 'english.m4a')
Convert-ToM4a (Join-Path $directory 'french.wav') (Join-Path $directory 'french.m4a')
Convert-ToM4a (Join-Path $directory 'long_french.wav') (Join-Path $directory 'long_french.m4a')

# --- silence: 5 s of digital zero ---
& $ffmpeg -hide_banner -loglevel error -y -f lavfi -i 'anullsrc=r=44100:cl=stereo' -t 5 `
    -c:a aac -b:a 128k (Join-Path $directory 'silence.m4a')
if ($LASTEXITCODE -ne 0) { throw 'ffmpeg failed for silence' }

# --- corrupt: random bytes, must fail cleanly instead of crashing ---
$noise = New-Object byte[] 16384
$generator = [System.Security.Cryptography.RandomNumberGenerator]::Create()
try {
    $generator.GetBytes($noise)
} finally {
    $generator.Dispose()
}
[System.IO.File]::WriteAllBytes((Join-Path $directory 'corrupt.m4a'), $noise)

# --- verify every fixture and record its duration for the tests ---
function Get-DurationMs([string]$file) {
    $raw = & $ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 $file
    if ($LASTEXITCODE -ne 0) { throw "ffprobe failed for $file" }
    return [int][math]::Round([double]::Parse($raw.Trim(), [Globalization.CultureInfo]::InvariantCulture) * 1000)
}

$fixtures = @('english.m4a', 'french.m4a', 'long_french.m4a', 'silence.m4a')
foreach ($name in $fixtures) {
    $path = Join-Path $directory $name
    $stream = & $ffprobe -v error -select_streams a:0 `
        -show_entries stream=codec_name,sample_rate,channels -of csv=p=0 $path
    if ($LASTEXITCODE -ne 0) { throw "ffprobe failed for $path" }
    $durationMs = Get-DurationMs $path
    # The tests compare word timestamps against the real clip length.
    Set-Content -Path (Join-Path $directory "$name.duration.txt") -Value $durationMs -NoNewline
    Write-Output ("{0,-20} {1}  duration={2} ms" -f $name, $stream.Trim(), $durationMs)
}

$corruptPath = Join-Path $directory 'corrupt.m4a'
Write-Output ("{0,-20} {1} bytes (not a media file)" -f 'corrupt.m4a', (Get-Item $corruptPath).Length)
Write-Output "Generated M4A test fixtures in $directory"
